<!DOCTYPE html>
<html lang="fr"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Mes Réclamations - ONAS</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.2/dist/css/bootstrap.min.css" rel="stylesheet"><style>body{background:#f8f9fa}.table-img{width:50px;height:50px;object-fit:cover;border-radius:6px;border:1px solid #dee2e6}.map-link{font-size:12px;color:#0d6efd;text-decoration:none}</style></head><body><nav class="navbar navbar-dark bg-success mb-4"><div class="container"><a class="navbar-brand" href="index.php?action=dashboard_citoyen">ONAS - Espace Citoyen</a><div><a href="index.php?action=dashboard_citoyen" class="btn btn-outline-light btn-sm me-2">Retour</a><form action="index.php?action=logout" method="POST" class="d-inline"><input type="hidden" name="csrf_token" value="<?=htmlspecialchars(csrfToken(),ENT_QUOTES,'UTF-8')?>"><button type="submit" class="btn btn-outline-light btn-sm">Déconnexion</button></form></div></div></nav><main class="container py-3"><div class="card shadow-sm border-0 p-4"><div class="d-flex justify-content-between align-items-center mb-4"><h3 class="text-secondary m-0">Liste de mes réclamations</h3><a href="index.php?action=ajouter" class="btn btn-success btn-sm">Nouvelle Réclamation</a></div><div class="table-responsive"><table class="table table-hover align-middle"><thead class="table-dark"><tr><th>ID</th><th>Type</th><th>Repère & GPS</th><th>Priorité</th><th>Photo</th><th>Statut</th></tr></thead><tbody><?php if(!empty($reclamations)&&is_array($reclamations)):foreach($reclamations as $r):$status=$r['statut']??'En attente';$priority=$r['priorite']??'Normale';?><tr><td>#<?= (int)($r['id_reclamation']??0) ?></td><td><strong><?=htmlspecialchars($r['type_probleme']??'',ENT_QUOTES,'UTF-8')?></strong></td><td><?=htmlspecialchars($r['repere']??'',ENT_QUOTES,'UTF-8')?><?php if(!empty($r['latitude'])&&!empty($r['longitude'])):?><br><a class="map-link" href="https://www.google.com/maps?q=<?=rawurlencode((string)$r['latitude'])?>,<?=rawurlencode((string)$r['longitude'])?>" target="_blank" rel="noopener noreferrer">Voir sur la carte</a><?php endif;?></td><td><span class="badge <?=$priority==='Urgente'?'bg-danger':'bg-warning text-dark'?>"><?=htmlspecialchars($priority,ENT_QUOTES,'UTF-8')?></span></td><td><?php if(!empty($r['photo'])):?><a href="<?=htmlspecialchars($r['photo'],ENT_QUOTES,'UTF-8')?>" target="_blank" rel="noopener noreferrer"><img src="<?=htmlspecialchars($r['photo'],ENT_QUOTES,'UTF-8')?>" alt="Photo réclamation" class="table-img"></a><?php else:?><span class="text-muted small">Aucune</span><?php endif;?></td><td><span class="badge <?=in_array($status,['Terminée','Traité'],true)?'bg-success':($status==='En cours'?'bg-primary':($status==='En attente'?'bg-warning text-dark':'bg-secondary'))?>"><?=htmlspecialchars($status,ENT_QUOTES,'UTF-8')?></span></td></tr><?php endforeach;else:?><tr><td colspan="6" class="text-center text-muted py-4">Vous n'avez aucune réclamation pour le moment.</td></tr><?php endif;?></tbody></table></div></div></main></body></html>